  total_bytes: number;
  /** Cross-campaign reuse caches (measurements/, optimizer_reuse/, judge_reuse/) —
   * survive delete */
  shared_cache_bytes: number;
  /** Everything else under the tenant: sessions, workspace ledger, dataset/backend
